example:
composition "Parametric EQ preview" { ample 1  tempo 100  master-seed 17 }

midi-clip phrase {
  chords Am F C G
  bars 4
}

synth source {
  wave saw
  gain -12 dB
  from phrase.notes -> notes
}

peq shape {
  band1_type lowshelf
  band1_hz 90 Hz
  band1_gain -4 dB
  band2_hz 400 Hz
  band2_gain -6 dB
  band2_q 2
  band3_hz 2200 Hz
  band3_gain 5 dB
  band3_q 0.8
  band4_type notch
  band4_hz 5000 Hz
  band4_q 6
  from source.audio -> audio
}

master master {
  from shape.audio -> audio
}
